<?php
declare(strict_types=1);
namespace App\Modules\CommercialRental\Models;
use App\Core\Database;
final class CommercialRentalCategory{private Database $db;public function __construct(){$this->db=app()->get('db');}public function all(int $t):array{return $this->db->fetchAll("SELECT * FROM commercial_rental_categories WHERE tenant_id=? AND deleted_at IS NULL ORDER BY name",[$t]);}public function find(int $t,int $id):?array{return $this->db->fetch("SELECT * FROM commercial_rental_categories WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$t,$id]);}public function create(int $t,array $d,int $u):int{$this->db->execute("INSERT INTO commercial_rental_categories(uuid,tenant_id,name,slug,description,status,created_by,updated_by) VALUES(UUID(),?,?,?,?,?,?,?)",[$t,$d['name'],$d['slug'],$d['description'],$d['status'],$u,$u]);return(int)$this->db->lastInsertId();}public function update(int $t,int $id,array $d,int $u):void{$this->db->execute("UPDATE commercial_rental_categories SET name=?,slug=?,description=?,status=?,updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$d['name'],$d['slug'],$d['description'],$d['status'],$u,$t,$id]);}public function delete(int $t,int $id,int $u):void{$this->db->execute("UPDATE commercial_rental_categories SET deleted_at=NOW(),updated_by=? WHERE tenant_id=? AND id=? AND deleted_at IS NULL",[$u,$t,$id]);}public function exists(int $t,string $slug,?int $ignore=null):bool{$sql="SELECT id FROM commercial_rental_categories WHERE tenant_id=? AND slug=? AND deleted_at IS NULL";$p=[$t,$slug];if($ignore!==null){$sql.=' AND id<>?';$p[]=$ignore;}return $this->db->fetch($sql.' LIMIT 1',$p)!==null;}public function count(int $t):int{$r=$this->db->fetch("SELECT COUNT(*) c FROM commercial_rental_categories WHERE tenant_id=? AND deleted_at IS NULL",[$t]);return(int)($r['c']??0);}}
